import{_ as t,l,o as e,c as i,v as s,p as n,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"KDF 与慢哈希","description":"","frontmatter":{"title":"KDF 与慢哈希","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kdf-slow-hash.md","filePath":"cs/kdf-slow-hash.md","lastUpdated":1789023840000}'),c={name:"cs/kdf-slow-hash.md"};function E(D,a,A,_,f,m){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=s('<h1 id="kdf-与慢哈希" tabindex="-1">KDF 与慢哈希 <a class="header-anchor" href="#kdf-与慢哈希" aria-label="Permalink to &quot;KDF 与慢哈希&quot;">​</a></h1><div class="epigraph"><p>从口令派生密钥必须贵而带盐；普通哈希太快，离线猜测会把低熵秘密一次试完。</p><footer>—— 据 PKCS #5 / PBKDF2；Morris and Thompson 对照；Anderson 对慢哈希的整理</footer></div><p><a href="/cs/password-salt">上一课</a>规定库里不存原文、要加盐。本课不重讲「盐打破彩虹表」。缺口是速度：SHA 一类摘要按设计很快，这对本课<a href="/cs/hash-collision">哈希碰撞</a> 的完整性用途是优点，对口令是缺点。KDF 与专门慢哈希把猜测变成算力与内存预算。认证协议下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口令课留下慢哈希一词。密钥派生函数（KDF）还有另一用途：从 DH 共享秘密拉出 AEAD 键（HKDF），那要快而均匀。口令 KDF 相反：故意慢、可调迭代、最好抗大规模并行。缺口是<strong>两种 KDF 不要用错场合</strong>。</p><p><span class="marginnote">参数（迭代、内存）随硬件涨。本课不点具体口令破解配置。防御是用为口令设计的函数，并保护哈希库本身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>口令：盐 + 慢 KDF，存派生结果。会话：HKDF 从高熵秘密派生，不套用口令参数。升级：算法标识与参数要和哈希一起存，才能迁函数。本课不比较全部函数商品名当选购广告。</p>',8)),(e(),n(p,null,{default:o(()=>[h(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PW%5B%22%E4%BD%8E%E7%86%B5%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20SLOW%5B%22%E6%85%A2%20KDF%20%E5%8A%A0%E7%9B%90%22%5D%0A%20%20SS%5B%22%E9%AB%98%E7%86%B5%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%22%5D%20--%3E%20HKDF%5B%22%E5%BF%AB%E9%80%9F%20HKDF%22%5D%0A%20%20SLOW%20--%3E%20STORE%5B%22%E5%AD%98%E5%82%A8%E6%B4%BE%E7%94%9F%E5%80%BC%22%5D%0A%20%20HKDF%20--%3E%20AEAD%5B%22%E4%BC%9A%E8%AF%9D%E9%94%AE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>慢哈希改变的是威胁模型里「抄库之后」的代价，不防止在线猜——在线要靠认证协议的限速与锁定。HKDF 服务<a href="/cs/dh-vs-rsa">DH 分工</a> 已得到的秘密。两者都不是加密算法本身。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入生物特征模板当口令替代。网上如何证明「此刻是谁」且抗重放，下一课认证协议。</p><p>后课默认：口令存储用慢 KDF。交互认证是另一套消息。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>口令派生必须慢且加盐；会话派生要快。</li><li>抄库后的离线猜测靠代价挡住，不是靠保密算法名。</li><li>认证协议下一课。</li><li>出处：PKCS #5；Morris and Thompson；Anderson。</li></ul>',7))])}const u=t(c,[["render",E]]);export{F as __pageData,u as default};
